using Microsoft.Extensions.Logging;using OrderFlow.Notifications.Application.Abstractions.Delivery;namespace OrderFlow.Notifications.Infrastructure.Delivery;public sealed class LoggingEmailSender(ILogger<LoggingEmailSender> logger):IEmailSender{public Task SendAsync(string recipient,string subject,string body,CancellationToken ct){ct.ThrowIfCancellationRequested();logger.LogInformation("Development email accepted for recipient hash {RecipientHash} subject length {SubjectLength} body length {BodyLength}",recipient.GetHashCode(StringComparison.Ordinal),subject.Length,body.Length);return Task.CompletedTask;}}
